case 'carousel': {
    // Vanz@Note --- tiap card WAJIB punya header.hasMediaAttachment: true (gambar/video).
    // Max 10 card per carousel — lebih dari itu bakal ke-truncate diem-diem di client.
    const rawCards = [
        {
            image: { url: "https://files.catbox.moe/ms64an.jpeg" },
            title: "Produk A",
            subtitle: "Rp150.000",
            body: "Deskripsi singkat produk A di sini.",
            footer: "• Vanzxy",
            buttons: [
                { name: "quick_reply", buttonParamsJson: JSON.stringify({ display_text: "Detail", id: "detail_a" }) },
                { name: "cta_url", buttonParamsJson: JSON.stringify({ display_text: "Beli Sekarang", url: "https://example.com/produk-a", merchant_url: "https://example.com" }) }
            ]
        },
        {
            image: { url: "https://files.catbox.moe/ms64an.jpeg" },
            title: "Produk B",
            subtitle: "Rp225.000",
            body: "Deskripsi singkat produk B di sini.",
            footer: "• Vanzxy",
            buttons: [
                { name: "quick_reply", buttonParamsJson: JSON.stringify({ display_text: "Detail", id: "detail_b" }) },
                { name: "cta_url", buttonParamsJson: JSON.stringify({ display_text: "Beli Sekarang", url: "https://example.com/produk-b", merchant_url: "https://example.com" }) }
            ]
        },
        {
            image: { url: "https://files.catbox.moe/ms64an.jpeg" },
            title: "Produk C",
            subtitle: "Rp99.000",
            body: "Deskripsi singkat produk C di sini.",
            footer: "• Vanzxy",
            buttons: [
                { name: "quick_reply", buttonParamsJson: JSON.stringify({ display_text: "Detail", id: "detail_c" }) },
                { name: "cta_url", buttonParamsJson: JSON.stringify({ display_text: "Beli Sekarang", url: "https://example.com/produk-c", merchant_url: "https://example.com" }) }
            ]
        }
    ];

    try {
        // Validasi akses
        if (!isRegistered(m.sender)) {
            return Reply(global.mess.verifikasi);
        }
        if (checkLimit(m.sender, global.isPrem(m.sender), isCreator)) {
            return Reply(global.mess.limit);
        }

        alip.sendMessage(m.chat, { react: { text: '⏳', key: m.key } });

        // Vanz@Fix: prepareWAMessageMedia butuh media DIBUNGKUS key tipenya
        // ({ image: {...} } atau { video: {...} }), bukan { url } polos — kalau
        // enggak, hasilnya undefined dan card gak ada gambarnya sama sekali.
        const cards = await Promise.all(
            rawCards.map(async (c) => ({
                body: { text: c.body },
                footer: { text: c.footer },
                header: {
                    title: c.title,
                    subtitle: c.subtitle,
                    hasMediaAttachment: true,
                    ...(await prepareWAMessageMedia({ image: c.image }, { upload: alip.uploadToServer }))
                },
                nativeFlowMessage: {
                    messageParamsJson: "{}",
                    buttons: c.buttons
                }
            }))
        );

        const msg = generateWAMessageFromContent(
            m.chat,
            {
                interactiveMessage: {
                    header: { hasMediaAttachment: false },
                    body: { text: "Geser buat liat produk lainnya 👉" },
                    footer: { text: "• Vanzxy" },
                    carouselMessage: { cards }
                }
            },
            { quoted: m }
        );

        await alip.relayMessage(msg.key.remoteJid, msg.message, {
            messageId: msg.key.id,
            additionalNodes: [
                {
                    tag: "biz",
                    attrs: {},
                    content: [
                        {
                            tag: "interactive",
                            attrs: { type: "native_flow", v: "1" },
                            content: [{ tag: "native_flow", attrs: { v: "9", name: "mixed" } }]
                        }
                    ]
                }
            ]
        });

        addLimit(m.sender, global.isPrem(m.sender), isCreator);
        // React success setelah proses selesai dan berhasil
        alip.sendMessage(m.chat, { react: { text: '✅', key: m.key } });

    } catch (e) {
        console.error("Error di case carousel:", e);
        Reply(`${global.mess.error} Terjadi kesalahan saat memproses carousel.`);
        // React gagal
        alip.sendMessage(m.chat, { react: { text: '❌', key: m.key } });
    }
}
